<script setup>
import { SHOPPING_OPERATION_PAGE_EVENTS, SHOPPING_OPERATION_PAGE_PROPS, localizeOperationPage } from './shopping-operation-page-contract'
const props=defineProps(SHOPPING_OPERATION_PAGE_PROPS); const emit=defineEmits(SHOPPING_OPERATION_PAGE_EVENTS); const l=(zh,en)=>localizeOperationPage(props.languageBase,zh,en)
</script>
<template>
<main class="ik-ops" :data-page="pageKey" data-testid="shopping-store-operation-page"><header class="ik-opbar"><button @click="emit('back')">←</button><strong><span>IKEA</span> KOREA</strong><div><button data-testid="shopping-open-service" @click="emit('open-service')">SERVICE</button><button @click="emit('open-orders')">PROJECTS</button><button @click="emit('open-cart')"><i class="fas fa-list-check"></i><b v-if="cartQuantity">{{ cartQuantity }}</b></button></div></header>
    <section v-if="pageKey==='cart'" id="shopping-cart" class="ik-list"><header><div><p>ROOM LIST / {{ cartQuantity }} OBJECTS</p><h1>{{ l('先确认房间，再确认购买','Confirm the room before confirming the purchase') }}</h1></div><div class="ik-room-mini"><i class="fas fa-couch"></i><span>ROOM 04</span></div></header><section class="ik-project-strip"><div><span>01</span><b>{{ l('尺寸','Measure') }}</b><small>PASSAGE / WALL / DEPTH</small></div><div><span>02</span><b>{{ l('包装','Packages') }}</b><small>{{ Math.max(1,cartQuantity) }} FLAT PACKS</small></div><div><span>03</span><b>{{ l('取货','Pickup') }}</b><small>SELECT AT REVIEW</small></div></section><div v-if="!cartItems.length" class="ik-empty">ROOM LIST EMPTY</div><div v-else class="ik-list-layout"><section><article v-for="line in cartItems" :key="line.productId"><span class="ik-object"><img v-if="productImageUrl(line.product)" :src="productImageUrl(line.product)" :alt="productDisplayTitle(line.product)" /><i v-else :class="productCategoryIcon(line.product)"></i><em>MEASURED</em></span><div><small>ROOM OBJECT</small><strong>{{ productDisplayTitle(line.product) }}</strong><dl><div><dt>PACK</dt><dd>{{ line.quantity }}</dd></div><div><dt>WIDTH</dt><dd>84 CM</dd></div></dl><b>{{ formatOrderItemSubtotal({ ...line,unitPriceCents:line.product.priceCents,currency:line.currency }) }}</b><div class="ik-qty"><button @click="emit('update-quantity',line.productId,-1)">−</button><span>{{ line.quantity }}</span><button @click="emit('update-quantity',line.productId,1)">+</button></div></div></article></section><aside><p>PROJECT REVIEW</p><strong>{{ cartTotalLabel }}</strong><div class="ik-transport"><i class="fas fa-car-side"></i><span>{{ l('搬运方式与自提点将在结算确认','Transport and pickup are confirmed at review') }}</span></div><label><input :checked="giftEnabled" type="checkbox" data-testid="shopping-gift-enabled" @change="emit('update:giftEnabled',$event.target.checked)" />{{ l('作为乔迁礼物','Housewarming gift') }}</label><select v-if="giftEnabled" :value="giftContactId" data-testid="shopping-gift-contact" @change="emit('update:giftContactId',$event.target.value)"><option value="">{{ l('手动收件人','Manual recipient') }}</option><option v-for="contact in giftRecipientOptions" :key="contact.id" :value="String(contact.id)">{{ contact.name }}</option></select><input v-if="giftEnabled" :value="giftRecipientName" data-testid="shopping-gift-name" @input="emit('update:giftRecipientName',$event.target.value)" /><button data-testid="shopping-checkout" @click="emit('checkout')">{{ l('创建房间项目','Create room project') }}</button></aside></div></section>
    <section v-else-if="pageKey==='orders'" id="shopping-orders" class="ik-projects"><header><div><p>ROOM PROJECTS</p><h1>{{ l('配送与组装项目','Delivery & assembly projects') }}</h1></div><button @click="emit('open-logistics')">DELIVERY BOARD →</button></header><article v-for="(order,index) in orders" :key="order.id" :data-testid="`shopping-order-${order.id}`"><div class="ik-plan"><span>PROJECT {{ String(index+1).padStart(2,'0') }}</span><i class="fas fa-ruler-combined"></i></div><div><small>{{ formatLogisticsDate(order.createdAt) }}</small><h2>{{ order.items.map(x=>x.title).join(' / ') }}</h2><p>{{ order.itemCount }} OBJECTS · {{ formatOrderTotal(order) }}</p><b>{{ orderStatusLabel(order.status) }}</b></div><button :data-testid="`shopping-open-order-detail-${order.id}`" @click="emit('open-order',order.id)">OPEN PLAN</button><button @click="emit('delete-order',order.id)">×</button></article><div v-if="!orders.length" class="ik-empty">NO ROOM PROJECTS</div></section>
