    <section v-else-if="selectedOrder" class="ik-detail" data-testid="shopping-order-detail-panel"><header><button data-testid="shopping-close-order-detail" @click="emit('close-order')">←</button><div><p>ROOM PROJECT DETAIL</p><h1>{{ selectedOrder.id }}</h1></div><b data-testid="shopping-order-detail-status">{{ orderStatusLabel(selectedOrder.status) }}</b></header><section class="ik-detail-blueprint"><div><span>PROJECT TOTAL</span><strong data-testid="shopping-order-detail-total">{{ formatOrderTotal(selectedOrder) }}</strong></div><i class="fas fa-couch"></i><b>{{ selectedOrder.itemCount }} OBJECTS / {{ selectedOrder.items.length }} PACK GROUPS</b></section><section class="ik-detail-items"><article v-for="item in selectedOrder.items" :key="item.id" :data-testid="`shopping-order-detail-item-${item.productId}`"><i class="fas fa-box-open"></i><div><h2>{{ item.title }}</h2><p>{{ item.quantity }} PACK · {{ formatOrderItemSubtotal(item) }}</p></div><strong>MEASURED</strong></article></section><section class="ik-detail-timeline" data-testid="shopping-order-detail-timeline"><h2>DELIVERY / ASSEMBLY NOTES</h2><article v-for="event in selectedOrder.events||[]" :key="event.id" :data-testid="`shopping-order-detail-event-${event.id}`"><span>{{ formatLogisticsDate(event.createdAt) }}</span><strong>{{ logisticsEventTypeLabel(event.type) }}</strong><p>{{ event.summary||event.title }}</p></article><p v-if="!selectedOrder.events?.length" data-testid="shopping-order-detail-timeline-empty">NO RECORDED PROJECT EVENTS</p></section><footer><button data-testid="shopping-order-detail-complete" :disabled="!canCompleteOrder(selectedOrder)" @click="emit('complete-order',selectedOrder.id)">COMPLETE PROJECT</button><button data-testid="shopping-order-detail-cancel" :disabled="!canCancelOrder(selectedOrder)" @click="emit('cancel-order',selectedOrder.id)">CANCEL</button><button data-testid="shopping-order-detail-delete" @click="emit('delete-order',selectedOrder.id)">DELETE</button></footer></section>
  </main>
